package com.pantryplan.app;
import android.app.*;import android.os.*;import android.content.*;import android.database.*;import android.database.sqlite.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import android.text.*;import java.time.*;

public class MainActivity extends Activity {
 SQLiteDatabase db; LinearLayout root,body,rows; String page="Pantry",filter="All",query=""; int window=3; boolean editing=false; long editId=-1; EditText draftName,draftQty,draftUnit; Spinner draftLoc; String[] draftDate; Button draftDateBtn;
 int green=Color.rgb(31,83,62), ink=Color.rgb(30,44,36), muted=Color.rgb(103,115,105);
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(green);getWindow().setNavigationBarColor(Color.WHITE);db=openOrCreateDatabase("pantry.db",MODE_PRIVATE,null);db.execSQL("CREATE TABLE IF NOT EXISTS food(id INTEGER PRIMARY KEY,name TEXT,quantity TEXT,unit TEXT,location TEXT,date TEXT)");db.execSQL("CREATE TABLE IF NOT EXISTS shopping(id INTEGER PRIMARY KEY,name TEXT,quantity TEXT,done INTEGER DEFAULT 0)");window=getPreferences(0).getInt("window",3);if(!getPreferences(0).getBoolean("seeded",false)){insertFood("Milk","1","bottle","Fridge",LocalDate.now().plusDays(2).toString());insertFood("Spinach","1","bag","Fridge",LocalDate.now().plusDays(1).toString());insertFood("Brown rice","2","kg","Pantry","");getPreferences(0).edit().putBoolean("seeded",true).apply();}if(b!=null){page=b.getString("page","Pantry");filter=b.getString("filter","All");query=b.getString("query","");}else if("com.pantryplan.REVIEW".equals(getIntent().getAction()))page="Dates";
 if(b!=null && b.getBoolean("editing")){editor(b.getLong("id"));draftName.setText(b.getString("name"));draftQty.setText(b.getString("qty"));draftUnit.setText(b.getString("unit"));draftLoc.setSelection(b.getInt("location"));draftDate[0]=b.getString("date","");draftDateBtn.setText(draftDate[0].isEmpty()?"Choose optional package date":draftDate[0]);}else show();}
 @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putString("page",page);b.putString("filter",filter);b.putString("query",query);b.putBoolean("editing",editing);if(editing){b.putLong("id",editId);b.putString("name",draftName.getText().toString());b.putString("qty",draftQty.getText().toString());b.putString("unit",draftUnit.getText().toString());b.putInt("location",draftLoc.getSelectedItemPosition());b.putString("date",draftDate[0]);}}
 @Override protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);if("com.pantryplan.REVIEW".equals(i.getAction())){page="Dates";show();}}
 @Override protected void onResume(){super.onResume();if(!editing&&(page.equals("Dates")||page.equals("Settings")))show();}
 @Override protected void onDestroy(){if(db!=null)db.close();super.onDestroy();}
 void say(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 void reminders(LinearLayout box){
 boolean enabled=getPreferences(0).getBoolean("remind",false), allowed=ReminderWorker.permitted(this);
 box.addView(text(enabled?(allowed?"On • one daily check":"Paused • notifications are blocked"):"Off",16,ink));
 box.addView(text("Get one summary for food dated today through the end of your chosen window. Android decides the delivery time.",14,muted));
 box.addView(button(enabled?"Turn off reminders":"Turn on reminders",()->{
 if(enabled){ReminderWorker.enable(this,false);show();return;}
 if(Build.VERSION.SDK_INT>=33 && checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},56);return;}
 if(!ReminderWorker.permitted(this)){say("Allow notifications in Android settings first.");return;}
 ReminderWorker.enable(this,true);show();}));
 if(!allowed)box.addView(button("Android notification settings",()->startActivity(new Intent(android.provider.Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(android.provider.Settings.EXTRA_APP_PACKAGE,getPackageName()))));
 if(enabled && allowed)box.addView(button("Check dates now",()->{int n=ReminderWorker.count(db,window);boolean posted=ReminderWorker.post(this,n);say(posted?"Summary sent. Tap the notification to see your dates.":n==0?"No upcoming package dates in this window.":"Notifications are blocked.");}));
 }
 @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] result){super.onRequestPermissionsResult(code,permissions,result);if(code==56){boolean ok=ReminderWorker.permitted(this);ReminderWorker.enable(this,ok);say(ok?"Daily reminders enabled.":"Reminders are off. You can still review dates in the app.");show();}}

 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);}
 LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
 TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(5),0,dp(5));return t;}
 void label(String s){body.addView(text(s,14,muted));}
 Button button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(green);b.setOnClickListener(v->r.run());return b;}
 LinearLayout card(){LinearLayout l=col();l.setPadding(dp(16),dp(12),dp(16),dp(12));GradientDrawable g=new GradientDrawable();g.setColor(Color.WHITE);g.setCornerRadius(dp(18));l.setBackground(g);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(6),0,dp(6));l.setLayoutParams(p);return l;}
 void shell(String title){root=col();root.setBackgroundColor(Color.rgb(243,246,239));root.setPadding(dp(18),dp(12),dp(18),0);setContentView(root);TextView brand=text("PANTRYPLAN  /  YOUR EVERYDAY FOOD COMPANION",10,green);root.addView(brand);TextView h=text(title,30,ink);h.setTypeface(null,Typeface.BOLD);root.addView(h);ScrollView scroll=new ScrollView(this);body=col();scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));}
 void nav(){LinearLayout bar=new LinearLayout(this);for(String s:new String[]{"Pantry","Dates","Shopping","Settings"}){Button b=button(s,()->{page=s;editing=false;show();});b.setTextSize(11);if(page.equals(s))b.setTypeface(null,Typeface.BOLD);bar.addView(b,new LinearLayout.LayoutParams(0,dp(60),1));}root.addView(bar);}
 void show(){editing=false;shell(page.equals("Dates")?"Expiring soon":page.equals("Shopping")?"Shopping list":page.equals("Settings")?"Your preferences":"Your pantry");if(page.equals("Pantry")){label("A little planning. Less forgotten food.");EditText search=new EditText(this);search.setSingleLine(true);search.setHint("Search your food");search.setText(query);body.addView(search);LinearLayout chips=new LinearLayout(this);for(String f:new String[]{"All","Pantry","Fridge","Freezer"}){Button b=button(f,()->{filter=f;show();});b.setTextSize(11);chips.addView(b,new LinearLayout.LayoutParams(0,-2,1));}body.addView(chips);label("Storage: "+filter);body.addView(button("+ Add food",()->editor(-1)));rows=col();body.addView(rows);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int d){}public void onTextChanged(CharSequence s,int a,int b,int c){query=s.toString();foods(false);}public void afterTextChanged(Editable e){}});foods(false);}else if(page.equals("Dates")){label("Package dates are reminders to review food, not a safety assessment.");windows();rows=col();body.addView(rows);foods(true);}else if(page.equals("Shopping")){label("Check off purchases. Update your pantry separately.");body.addView(button("+ Add shopping item",()->shopEditor(-1,"","1")));body.addView(button("Clear purchased",()->confirm("Remove purchased items?",()->{db.delete("shopping","done=1",null);show();})));try(Cursor c=db.rawQuery("SELECT id,name,quantity,done FROM shopping ORDER BY done,id DESC",null)){if(c.getCount()==0)label("Your list is clear. Add something for your next shop.");while(c.moveToNext()){long id=c.getLong(0);String name=c.getString(1),qty=c.getString(2);LinearLayout box=card();CheckBox check=new CheckBox(this);check.setText(name+" · "+qty);check.setTextSize(18);check.setChecked(c.getInt(3)==1);check.setOnCheckedChangeListener((v,on)->{ContentValues cv=new ContentValues();cv.put("done",on?1:0);db.update("shopping",cv,"id=?",new String[]{""+id});show();});box.addView(check);box.addView(button("Edit",()->shopEditor(id,name,qty)));box.addView(button("Delete",()->confirm("Delete this shopping item?",()->{db.delete("shopping","id=?",new String[]{""+id});show();})));body.addView(box);}}}else{label("Choose how far ahead to review package dates.");windows();LinearLayout box=card();box.addView(text("Daily reminders",20,ink));reminders(box);body.addView(box);label("Your food and shopping records are saved on this device using SQLite. No account or internet required.");label("PantryPlan • Group P 56\nTaharim Haque · Fatma Akkoca · Punar Sharifli");}nav();}
 void windows(){LinearLayout l=new LinearLayout(this);for(int n:new int[]{1,3,7})l.addView(button((window==n?"✓ ":"")+n+(n==1?" day":" days"),()->{window=n;getPreferences(0).edit().putInt("window",n).apply();show();}),new LinearLayout.LayoutParams(0,-2,1));body.addView(l);}
 void foods(boolean dates){rows.removeAllViews();int count=0;PantryReview.Group previous=null;LocalDate today=LocalDate.now();try(Cursor c=db.rawQuery("SELECT id,name,quantity,unit,location,date FROM food ORDER BY CASE WHEN date='' THEN 1 ELSE 0 END,date,name",null)){while(c.moveToNext()){long id=c.getLong(0);String name=c.getString(1),qty=c.getString(2),unit=c.getString(3),loc=c.getString(4),date=c.getString(5);PantryReview.Group group=PantryReview.group(date,today,window);if(dates){if(group!=PantryReview.Group.PASSED && group!=PantryReview.Group.UPCOMING)continue;if(previous!=group){TextView h=text(group==PantryReview.Group.PASSED?"Passed dates":"Today and upcoming",19,green);h.setTypeface(null,Typeface.BOLD);rows.addView(h);previous=group;}}if(!dates&&(!name.toLowerCase().contains(query.toLowerCase())||(!filter.equals("All")&&!loc.equals(filter))))continue;count++;LinearLayout box=card();box.addView(text(name,22,ink));box.addView(text(qty+" "+unit+"  •  "+loc,14,muted));String status=group==PantryReview.Group.UNDATED?"No package date":group==PantryReview.Group.PASSED?"Passed date · "+date:today.toString().equals(date)?"Package date today":"Package date · "+date;box.addView(text(status,14,group==PantryReview.Group.PASSED?Color.rgb(160,65,36):green));box.addView(button("Edit food",()->editor(id)));box.addView(button("+ Shopping list",()->{ContentValues cv=new ContentValues();cv.put("name",name);cv.put("quantity",qty+" "+unit);db.insert("shopping",null,cv);Toast.makeText(this,"Added to shopping list",Toast.LENGTH_SHORT).show();}));rows.addView(box);}}if(count==0)rows.addView(text(dates?"Nothing to review in this window.":"No food matches. Add food or change your filters.",16,muted));}
 EditText input(String hint,String val){label(hint);EditText e=new EditText(this);e.setSingleLine(true);e.setText(val);e.setHint(hint);body.addView(e);return e;}
 void editor(long id){editId=id;editing=true;shell(id<0?"Add food":"Edit food");String[] v={"","1","items","Pantry",""};if(id>=0)try(Cursor c=db.rawQuery("SELECT name,quantity,unit,location,date FROM food WHERE id=?",new String[]{""+id})){if(c.moveToFirst())for(int i=0;i<5;i++)v[i]=c.getString(i);}EditText name=input("Food name",v[0]),qty=input("Quantity",v[1]),unit=input("Unit (kg, bag, bottle…)",v[2]);qty.setInputType(8194);label("Storage location");Spinner location=new Spinner(this);String[] locs={"Pantry","Fridge","Freezer"};location.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,locs));for(int i=0;i<3;i++)if(locs[i].equals(v[3]))location.setSelection(i);body.addView(location);final String[] date={v[4]};Button dateBtn=button(date[0].isEmpty()?"Choose optional package date":date[0],()->{});dateBtn.setOnClickListener(w->{LocalDate d=date[0].isEmpty()?LocalDate.now():LocalDate.parse(date[0]);new DatePickerDialog(this,(p,y,m,day)->{date[0]=LocalDate.of(y,m+1,day).toString();dateBtn.setText(date[0]);},d.getYear(),d.getMonthValue()-1,d.getDayOfMonth()).show();});draftName=name;draftQty=qty;draftUnit=unit;draftLoc=location;draftDate=date;draftDateBtn=dateBtn;body.addView(dateBtn);body.addView(button("Remove date",()->{date[0]="";dateBtn.setText("Choose optional package date");}));body.addView(button("Save food",()->{String n=name.getText().toString().trim(),q=qty.getText().toString().trim(),u=unit.getText().toString().trim();if(n.isEmpty()){name.setError("Enter a food name");return;}try{double x=Double.parseDouble(q);if(!Double.isFinite(x)||x<=0)throw new Exception();}catch(Exception e){qty.setError("Enter a positive quantity");return;}if(u.isEmpty()){unit.setError("Enter a unit");return;}ContentValues cv=new ContentValues();cv.put("name",n);cv.put("quantity",q);cv.put("unit",u);cv.put("location",location.getSelectedItem().toString());cv.put("date",date[0]);if(id<0)db.insert("food",null,cv);else db.update("food",cv,"id=?",new String[]{""+id});show();}));body.addView(button("Cancel",()->show()));if(id>=0)body.addView(button("Delete food",()->confirm("Delete this food record?",()->{db.delete("food","id=?",new String[]{""+id});show();})));}
 void shopEditor(long id,String n,String q){LinearLayout l=col();l.setPadding(dp(20),0,dp(20),0);EditText name=new EditText(this),qty=new EditText(this);name.setHint("Item name");name.setText(n);qty.setHint("Amount, e.g. 2 bags");qty.setText(q);l.addView(name);l.addView(qty);AlertDialog d=new AlertDialog.Builder(this).setTitle(id<0?"Add purchase":"Edit purchase").setView(l).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();d.setOnShowListener(w->d.getButton(-1).setOnClickListener(b->{if(name.getText().toString().trim().isEmpty()){name.setError("Enter a name");return;}if(qty.getText().toString().trim().isEmpty()){qty.setError("Enter an amount");return;}ContentValues cv=new ContentValues();cv.put("name",name.getText().toString().trim());cv.put("quantity",qty.getText().toString().trim());if(id<0)db.insert("shopping",null,cv);else db.update("shopping",cv,"id=?",new String[]{""+id});d.dismiss();show();}));d.show();}
 void confirm(String s,Runnable r){new AlertDialog.Builder(this).setMessage(s).setNegativeButton("Cancel",null).setPositiveButton("Delete",(d,w)->r.run()).show();}
 void insertFood(String n,String q,String u,String l,String d){ContentValues v=new ContentValues();v.put("name",n);v.put("quantity",q);v.put("unit",u);v.put("location",l);v.put("date",d);db.insert("food",null,v);}
 @Override public void onBackPressed(){if(editing){show();}else if(!page.equals("Pantry")){page="Pantry";show();}else super.onBackPressed();}
}
